window.PHYSICS_CHAPTERS = [
{id:1,name:'Quantities & Measurement'},{id:2,name:'Forces and Moments'},{id:3,name:'Motion and Forces'},{id:4,name:'Energy and Fields'},{id:5,name:'Projectile Motion'},{id:6,name:'Collisions'},{id:7,name:'Circular Motion'},{id:8,name:'Gravitational Fields'},{id:9,name:'Oscillations'},{id:10,name:'Wave Motion'},{id:11,name:'Superposition'},{id:12,name:'Temperature and Ideal Gases'},{id:13,name:'Thermodynamic Systems'},{id:14,name:'Electric Fields'},{id:15,name:'Currents'},{id:16,name:'Circuits'},{id:17,name:'Electromagnetic Forces'},{id:18,name:'Electromagnetic Induction'},{id:19,name:'Quantum Physics'},{id:20,name:'Nuclear Physics'}];
window.PHYSICS_CARDS = [
// Chapter 1
{ id:'c1a',chapter:1,type:'Definition',question:'Define a base quantity.',answer:'A physical quantity that is chosen and defined independently and is not derived from other physical quantities.'},
{ id:'c1b',chapter:1,type:'Definition',question:'Distinguish between a scalar and a vector quantity.',answer:'A scalar has magnitude only. A vector has both magnitude and direction.'},
{ id:'c1c',chapter:1,type:'Definition',question:'Distinguish between random error and systematic error.',answer:'Random errors cause unpredictable variations between measurements. Systematic errors shift measurements consistently in the same direction, for example due to zero error.'},
{ id:'c1d',chapter:1,type:'Formula',question:'How is percentage uncertainty calculated?',answer:'Percentage uncertainty = (absolute uncertainty / measured value) × 100%.'},
{ id:'c1e',chapter:1,type:'Definition',question:'What is the principle for combining uncertainties when quantities are added or subtracted?',answer:'Add the absolute uncertainties of the measured quantities.'},
{ id:'c1f',chapter:1,type:'Definition',question:'What is the SI base unit of thermodynamic temperature?',answer:'Kelvin (K).'},
// Chapter 2
{ id:'c2a',chapter:2,type:'Definition',question:'Define the moment of a force about a point.',answer:'Moment = force × perpendicular distance from the point to the line of action of the force.'},
{ id:'c2b',chapter:2,type:'Definition',question:'State the principle of moments.',answer:'For a body in rotational equilibrium, the sum of clockwise moments about any point equals the sum of anticlockwise moments about that point.'},
{ id:'c2c',chapter:2,type:'Definition',question:'What is a couple?',answer:'A pair of equal and opposite parallel forces whose lines of action are separated, producing a turning effect only.'},
{ id:'c2d',chapter:2,type:'Formula',question:'State Hooke’s law.',answer:'F = kx, where F is the force, k is the force constant and x is the extension or compression, within the limit of proportionality.'},
{ id:'c2e',chapter:2,type:'Definition',question:'What are the conditions for complete equilibrium?',answer:'The resultant force is zero and the resultant torque (or moment) about any point is zero.'},
{ id:'c2f',chapter:2,type:'Definition',question:'What is the centre of gravity of a body?',answer:'The point at which the entire weight of the body may be considered to act.'},
// Chapter 3
{ id:'c3a',chapter:3,type:'Definition',question:'Define acceleration.',answer:'The rate of change of velocity with respect to time.'},
{ id:'c3b',chapter:3,type:'Formula',question:'State the three standard equations of uniformly accelerated linear motion.',answer:'v = u + at; s = (u + v)t/2; s = ut + ½at²; v² = u² + 2as. Use when acceleration is constant.'},
{ id:'c3c',chapter:3,type:'Definition',question:'What does the gradient of a displacement–time graph represent?',answer:'Velocity.'},
{ id:'c3d',chapter:3,type:'Definition',question:'What does the gradient and area under a velocity–time graph represent?',answer:'Gradient = acceleration. Signed area under the graph = displacement.'},
{ id:'c3e',chapter:3,type:'Definition',question:'State Newton’s second law in terms of momentum.',answer:'The rate of change of momentum of a body is proportional to the resultant force and occurs in the direction of that force.'},
{ id:'c3f',chapter:3,type:'Formula',question:'Write the relationship between resultant force and acceleration for constant mass.',answer:'F = ma, where F is resultant force, m is mass and a is acceleration.'},
{ id:'c3g',chapter:3,type:'Definition',question:'Define linear momentum.',answer:'The product of a body’s mass and velocity: p = mv.'},
// Chapter 4
{ id:'c4a',chapter:4,type:'Definition',question:'Define work done by a constant force.',answer:'The product of the force and the displacement in the direction of the force: W = Fs cos θ.'},
{ id:'c4b',chapter:4,type:'Formula',question:'State the equation for kinetic energy.',answer:'Eₖ = ½mv².'},
{ id:'c4c',chapter:4,type:'Definition',question:'Define power.',answer:'The rate of energy transfer or the rate at which work is done.'},
{ id:'c4d',chapter:4,type:'Formula',question:'State the equation for mechanical power when force and velocity are aligned.',answer:'P = Fv.'},
{ id:'c4e',chapter:4,type:'Definition',question:'Define gravitational field strength.',answer:'Gravitational force per unit mass acting on a small test mass at a point in the field.'},
{ id:'c4f',chapter:4,type:'Formula',question:'How is efficiency defined?',answer:'Efficiency = useful energy output / total energy input, or useful power output / total power input.'},
{ id:'c4g',chapter:4,type:'Formula',question:'State the elastic potential energy represented by a force–extension graph.',answer:'The area under the force–extension graph gives the elastic potential energy stored (for a linear spring, E = ½Fx = ½kx²).'},
// Chapter 5
{ id:'c5a',chapter:5,type:'Formula',question:'State the change in gravitational potential energy near Earth’s surface.',answer:'ΔEₚ = mgΔh, assuming g is approximately constant.'},
{ id:'c5b',chapter:5,type:'Definition',question:'What is meant by free fall?',answer:'Motion in which gravity is the only force acting on the body (air resistance is negligible).'},
{ id:'c5c',chapter:5,type:'Definition',question:'Explain terminal velocity.',answer:'The constant velocity reached when the resistive force balances the weight, making the resultant force and acceleration zero.'},
{ id:'c5d',chapter:5,type:'Concept',question:'For ideal projectile motion, what happens to horizontal and vertical motion?',answer:'Horizontal velocity is constant (no horizontal acceleration); vertical acceleration is g downward. The components are independent.'},
{ id:'c5e',chapter:5,type:'Definition',question:'Why does a falling object reach terminal velocity in a fluid?',answer:'As speed rises, drag increases until drag equals weight; resultant force becomes zero and speed stops increasing.'},
// Chapter 6
{ id:'c6a',chapter:6,type:'Definition',question:'Define impulse.',answer:'The product of force and the time interval for which it acts; for a varying force it is the area under the force–time graph.'},
{ id:'c6b',chapter:6,type:'Formula',question:'State the impulse–momentum relationship.',answer:'Impulse = change in momentum: J = Δp. For a constant net force, FΔt = Δp.'},
{ id:'c6c',chapter:6,type:'Definition',question:'State the principle of conservation of momentum.',answer:'The total momentum of a system remains constant if the resultant external force on the system is zero.'},
{ id:'c6d',chapter:6,type:'Definition',question:'What is true of kinetic energy in an elastic collision?',answer:'Total kinetic energy is conserved. For a one-dimensional elastic collision, relative speed of approach equals relative speed of separation.'},
{ id:'c6e',chapter:6,type:'Concept',question:'Is kinetic energy always conserved in a collision?',answer:'No. Momentum is conserved for a closed system, but kinetic energy is generally transformed into other forms unless the collision is elastic.'},
// Chapter 7
{ id:'c7a',chapter:7,type:'Formula',question:'Relate linear speed and angular speed in circular motion.',answer:'v = rω, where r is radius and ω is angular velocity.'},
{ id:'c7b',chapter:7,type:'Formula',question:'State the two equivalent expressions for centripetal acceleration.',answer:'a = rω² = v²/r, directed towards the centre.'},
{ id:'c7c',chapter:7,type:'Formula',question:'State the centripetal force equation.',answer:'F = mrω² = mv²/r. It is the resultant force directed towards the centre, not a separate type of force.'},
{ id:'c7d',chapter:7,type:'Definition',question:'Why is an object moving at constant speed in a circle accelerating?',answer:'Its velocity direction changes continuously, so its velocity changes even though its speed is constant.'},
{ id:'c7e',chapter:7,type:'Definition',question:'What is angular velocity?',answer:'The rate of change of angular displacement; its SI unit is rad s⁻¹.'},
// Chapter 8
{ id:'c8a',chapter:8,type:'Formula',question:'State Newton’s law of gravitation.',answer:'F = GMm/r² for two point masses M and m separated by distance r; the force is attractive.'},
{ id:'c8b',chapter:8,type:'Definition',question:'Define gravitational potential at a point.',answer:'Work done per unit mass by an external force in bringing a small test mass from infinity to that point, without change in kinetic energy.'},
{ id:'c8c',chapter:8,type:'Formula',question:'State the gravitational field strength and potential for a point mass.',answer:'g = GM/r² (magnitude, towards the mass); φ = −GM/r, taking potential to be zero at infinity.'},
{ id:'c8d',chapter:8,type:'Formula',question:'State the gravitational potential energy of two point masses.',answer:'U₉ = −GMm/r, with zero potential energy at infinite separation.'},
{ id:'c8e',chapter:8,type:'Concept',question:'What makes a satellite stay in circular orbit?',answer:'Gravitational force provides the centripetal resultant force needed for circular motion.'},
{ id:'c8f',chapter:8,type:'Definition',question:'What is a geostationary satellite?',answer:'A satellite orbiting above the equator in the same direction as Earth’s rotation, with a 24-hour period, appearing stationary relative to the ground.'},
// Chapter 9
{ id:'c9a',chapter:9,type:'Definition',question:'Define simple harmonic motion (SHM).',answer:'Oscillation in which acceleration is directly proportional to displacement from equilibrium and always directed towards equilibrium: a = −ω²x.'},
{ id:'c9b',chapter:9,type:'Formula',question:'State the relation between period, frequency and angular frequency.',answer:'T = 1/f and ω = 2πf = 2π/T.'},
{ id:'c9c',chapter:9,type:'Formula',question:'Give a displacement equation for SHM.',answer:'x = x₀ sin(ωt) is one possible form, depending on the chosen phase at t = 0.'},
{ id:'c9d',chapter:9,type:'Definition',question:'What is resonance?',answer:'A large-amplitude response of a forced oscillator when the driving frequency is close to its natural frequency.'},
{ id:'c9e',chapter:9,type:'Definition',question:'Distinguish between light and heavy damping.',answer:'Light damping causes amplitude to decrease gradually; heavy damping returns the system to equilibrium slowly without oscillating.'},
{ id:'c9f',chapter:9,type:'Concept',question:'How is energy exchanged during ideal SHM?',answer:'Kinetic and potential energy interchange; total mechanical energy remains constant in the absence of damping.'},
// Chapter 10
{ id:'c10a',chapter:10,type:'Definition',question:'Define a progressive wave.',answer:'A travelling disturbance that transfers energy from place to place without net transfer of matter.'},
{ id:'c10b',chapter:10,type:'Formula',question:'State the wave speed equation.',answer:'v = fλ, where v is wave speed, f is frequency and λ is wavelength.'},
{ id:'c10c',chapter:10,type:'Definition',question:'Distinguish between transverse and longitudinal waves.',answer:'Transverse: oscillations are perpendicular to energy transfer. Longitudinal: oscillations are parallel to energy transfer.'},
{ id:'c10d',chapter:10,type:'Definition',question:'Define intensity of a wave.',answer:'Power transferred (or radiated) per unit area normal to the direction of energy transfer.'},
{ id:'c10e',chapter:10,type:'Formula',question:'How does wave intensity relate to amplitude for a progressive wave?',answer:'Intensity ∝ (amplitude)².'},
{ id:'c10f',chapter:10,type:'Definition',question:'What is polarisation and which waves can be polarised?',answer:'Polarisation restricts oscillations to one direction or plane; it is a phenomenon of transverse waves.'},
// Chapter 11
{ id:'c11a',chapter:11,type:'Definition',question:'State the principle of superposition.',answer:'When two or more waves meet, the resultant displacement at a point is the vector sum of their individual displacements.'},
{ id:'c11b',chapter:11,type:'Definition',question:'What are coherent sources?',answer:'Sources that have the same frequency and maintain a constant phase difference.'},
{ id:'c11c',chapter:11,type:'Formula',question:'State the double-slit fringe-spacing relationship.',answer:'x = λD/a, where x is fringe separation, λ is wavelength, D is slit-to-screen distance and a is slit separation.'},
{ id:'c11d',chapter:11,type:'Formula',question:'State the diffraction grating condition for principal maxima.',answer:'a sin θ = nλ, where a is slit separation and n is an integer order.'},
{ id:'c11e',chapter:11,type:'Formula',question:'State the condition for minima in single-slit diffraction.',answer:'b sin θ = nλ for minima, where b is slit width and n = 1, 2, 3, …'},
{ id:'c11f',chapter:11,type:'Definition',question:'What is a node in a standing wave?',answer:'A point that remains at zero displacement at all times.'},
{ id:'c11g',chapter:11,type:'Definition',question:'What is an antinode in a standing wave?',answer:'A point where the oscillation amplitude is maximum.'},
// Chapter 12
{ id:'c12a',chapter:12,type:'Formula',question:'Convert a Celsius temperature to kelvin.',answer:'T/K = θ/°C + 273.15.'},
{ id:'c12b',chapter:12,type:'Formula',question:'State the ideal gas equation using number of particles.',answer:'pV = NkT, where N is number of particles and k is the Boltzmann constant.'},
{ id:'c12c',chapter:12,type:'Formula',question:'State the ideal gas equation using amount of substance.',answer:'pV = nRT, where n is amount in moles and R is the molar gas constant.'},
{ id:'c12d',chapter:12,type:'Definition',question:'State the basic kinetic theory assumptions for an ideal gas.',answer:'Particles are in continuous random motion; their own volume is negligible; intermolecular forces are negligible except during collisions; collisions are perfectly elastic; motion obeys Newtonian mechanics.'},
{ id:'c12e',chapter:12,type:'Formula',question:'Relate mean translational kinetic energy per ideal-gas particle to temperature.',answer:'½m⟨c²⟩ = ³⁄₂kT.'},
{ id:'c12f',chapter:12,type:'Formula',question:'State the kinetic theory equation linking pressure and mean-square speed.',answer:'pV = ⅓Nm⟨c²⟩.'},
// Chapter 13
{ id:'c13a',chapter:13,type:'Definition',question:'Define the internal energy of a system.',answer:'The sum of the microscopic kinetic and potential energies of the particles in the system.'},
{ id:'c13b',chapter:13,type:'Definition',question:'State the zeroth law of thermodynamics.',answer:'If two systems are each in thermal equilibrium with a third system, they are in thermal equilibrium with each other.'},
{ id:'c13c',chapter:13,type:'Formula',question:'State the first law of thermodynamics using the sign convention in the notes.',answer:'ΔU = Q + W, where Q is energy transferred to the system by heating and W is work done on the system.'},
{ id:'c13d',chapter:13,type:'Formula',question:'State the work done by a gas expanding against constant external pressure.',answer:'Work done by gas = pΔV, for constant external pressure.'},
{ id:'c13e',chapter:13,type:'Definition',question:'Define specific heat capacity.',answer:'Energy required to raise the temperature of unit mass of a substance by one kelvin, without change of state.'},
{ id:'c13f',chapter:13,type:'Definition',question:'Define specific latent heat.',answer:'Energy required per unit mass to change the state of a substance without changing its temperature.'},
// Chapter 14
{ id:'c14a',chapter:14,type:'Formula',question:'State Coulomb’s law for two point charges.',answer:'F = |Q₁Q₂|/(4πε₀r²) in free space or air; the force acts along the line joining the charges.'},
{ id:'c14b',chapter:14,type:'Formula',question:'State electric field strength due to a point charge.',answer:'E = Q/(4πε₀r²) in magnitude; direction is away from a positive source charge and towards a negative source charge.'},
{ id:'c14c',chapter:14,type:'Definition',question:'Define electric potential at a point.',answer:'Work done per unit positive charge by an external force in bringing a small test charge from infinity to that point, without change in kinetic energy.'},
{ id:'c14d',chapter:14,type:'Formula',question:'State electric potential due to a point charge.',answer:'V = Q/(4πε₀r), taking potential to be zero at infinity.'},
{ id:'c14e',chapter:14,type:'Formula',question:'State the electric field strength between parallel plates.',answer:'E = V/d for a uniform field, where V is potential difference and d is plate separation.'},
{ id:'c14f',chapter:14,type:'Definition',question:'Define capacitance.',answer:'The ratio of charge stored to potential difference: C = Q/V.'},
{ id:'c14g',chapter:14,type:'Formula',question:'State the energy stored in a capacitor.',answer:'U = ½QV = Q²/(2C) = ½CV².'},
// Chapter 15
{ id:'c15a',chapter:15,type:'Definition',question:'Define electric current.',answer:'The rate of flow of electric charge: I = dQ/dt (or I = Q/t for steady current).'},
{ id:'c15b',chapter:15,type:'Formula',question:'State the drift-current equation.',answer:'I = nAvq, where n is charge-carrier number density, A is cross-sectional area, v is drift speed and q is charge magnitude.'},
{ id:'c15c',chapter:15,type:'Definition',question:'Define potential difference.',answer:'Electrical work done per unit charge transferred between two points: V = W/Q.'},
{ id:'c15d',chapter:15,type:'Formula',question:'State three equivalent equations for electrical power in a resistor.',answer:'P = VI = I²R = V²/R.'},
{ id:'c15e',chapter:15,type:'Definition',question:'Distinguish between e.m.f. and potential difference.',answer:'E.m.f. is energy supplied by a source per unit charge. Potential difference is energy transferred from electrical energy to other forms per unit charge between two points.'},
{ id:'c15f',chapter:15,type:'Formula',question:'State the relationship between peak and r.m.s. values for a sinusoidal a.c.',answer:'Iᵣₘₛ = I₀/√2 and Vᵣₘₛ = V₀/√2.'},
// Chapter 16
{ id:'c16a',chapter:16,type:'Formula',question:'State Ohm’s law in equation form.',answer:'V = IR for an ohmic conductor at constant physical conditions.'},
{ id:'c16b',chapter:16,type:'Formula',question:'State the resistance–resistivity relationship.',answer:'R = ρL/A, where ρ is resistivity, L is length and A is cross-sectional area.'},
{ id:'c16c',chapter:16,type:'Formula',question:'How do you combine resistors in series?',answer:'R_total = R₁ + R₂ + …'},
{ id:'c16d',chapter:16,type:'Formula',question:'How do you combine resistors in parallel?',answer:'1/R_total = 1/R₁ + 1/R₂ + …'},
{ id:'c16e',chapter:16,type:'Formula',question:'State the time constant for an RC circuit.',answer:'τ = RC, where R is resistance and C is capacitance.'},
{ id:'c16f',chapter:16,type:'Formula',question:'State the capacitor charging and discharging relationships.',answer:'Discharging: x = x₀e^(−t/RC). Charging: x = x₀[1 − e^(−t/RC)] for a quantity that rises from zero towards x₀.'},
{ id:'c16g',chapter:16,type:'Concept',question:'How does an NTC thermistor’s resistance change as temperature rises?',answer:'Its resistance decreases as temperature rises, because the semiconductor’s charge-carrier number density increases.'},
// Chapter 17
{ id:'c17a',chapter:17,type:'Formula',question:'State the magnetic flux density due to a long straight current-carrying wire.',answer:'B = μ₀I/(2πd), where d is the perpendicular distance from the wire.'},
{ id:'c17b',chapter:17,type:'Formula',question:'State the magnetic flux density at the centre of a flat circular coil of N turns.',answer:'B = μ₀NI/(2r), for a coil of radius r.'},
{ id:'c17c',chapter:17,type:'Formula',question:'State the magnetic flux density inside a long solenoid.',answer:'B = μ₀nI, where n is the number of turns per unit length.'},
{ id:'c17d',chapter:17,type:'Formula',question:'State the force on a current-carrying conductor in a magnetic field.',answer:'F = BIl sin θ, where θ is the angle between current direction and magnetic field.'},
{ id:'c17e',chapter:17,type:'Definition',question:'Define magnetic flux density using the force on a conductor.',answer:'The force per unit current per unit length on a conductor placed perpendicular to the magnetic field.'},
{ id:'c17f',chapter:17,type:'Formula',question:'State the magnetic force on a moving charge.',answer:'F = BQv sin θ, where θ is the angle between velocity and magnetic field.'},
// Chapter 18
{ id:'c18a',chapter:18,type:'Definition',question:'Define magnetic flux through a surface in a uniform magnetic field.',answer:'Φ = BA when the field is perpendicular to the surface; more generally Φ = BA cos θ, with θ between B and the surface normal.'},
{ id:'c18b',chapter:18,type:'Formula',question:'State magnetic flux linkage for a coil of N turns.',answer:'NΦ = NBA for a uniform field perpendicular to the coil.'},
{ id:'c18c',chapter:18,type:'Definition',question:'State Faraday’s law of electromagnetic induction.',answer:'The magnitude of the induced e.m.f. is proportional to the rate of change of magnetic flux linkage: |ε| = |d(NΦ)/dt|.'},
{ id:'c18d',chapter:18,type:'Definition',question:'State Lenz’s law.',answer:'The induced current flows in a direction such that its magnetic effect opposes the change in magnetic flux that produced it.'},
{ id:'c18e',chapter:18,type:'Formula',question:'State the ideal transformer equation.',answer:'Vₛ/Vₚ = Nₛ/Nₚ = Iₚ/Iₛ.'},
{ id:'c18f',chapter:18,type:'Concept',question:'What is required to induce an e.m.f. in a coil?',answer:'A change in magnetic flux linkage through the coil.'},
// Chapter 19
{ id:'c19a',chapter:19,type:'Definition',question:'What is a photon?',answer:'A quantum (discrete packet) of electromagnetic radiation.'},
{ id:'c19b',chapter:19,type:'Formula',question:'State the energy of a photon.',answer:'E = hf = hc/λ.'},
{ id:'c19c',chapter:19,type:'Formula',question:'State the momentum of a photon.',answer:'p = E/c = h/λ.'},
{ id:'c19d',chapter:19,type:'Definition',question:'What does the photoelectric effect show about light?',answer:'The existence of a threshold frequency supports the particulate nature of electromagnetic radiation; photon energy depends on frequency, E = hf.'},
{ id:'c19e',chapter:19,type:'Formula',question:'State the de Broglie wavelength relationship.',answer:'λ = h/p for a particle of momentum p.'},
{ id:'c19f',chapter:19,type:'Definition',question:'What does |Ψ|² represent?',answer:'The probability density of finding the particle at a given position.'},
{ id:'c19g',chapter:19,type:'Formula',question:'State the energy levels for a particle in a one-dimensional infinite square well.',answer:'Eₙ = (h²n²)/(8mL²), where n = 1, 2, 3, … and L is the well width.'},
{ id:'c19h',chapter:19,type:'Concept',question:'When is a photon absorbed during an atomic transition?',answer:'When its energy exactly equals the difference between two allowed energy levels.'},
{ id:'c19i',chapter:19,type:'Definition',question:'Distinguish between emission and absorption line spectra.',answer:'Emission: bright lines at specific wavelengths on a dark background. Absorption: dark lines missing from a continuous spectrum.'},
{ id:'c19j',chapter:19,type:'Formula',question:'State the Heisenberg position–momentum uncertainty relation as given in your notes.',answer:'ΔxΔp ≳ h. Greater localisation (smaller Δx) requires a larger spread in momentum Δp.'},
// Chapter 20
{ id:'c20a',chapter:20,type:'Definition',question:'Distinguish between proton number and nucleon number.',answer:'Proton number Z is the number of protons. Nucleon number A is the total number of protons and neutrons.'},
{ id:'c20b',chapter:20,type:'Definition',question:'What are isotopes?',answer:'Atoms/nuclides of the same element with the same proton number but different numbers of neutrons.'},
{ id:'c20c',chapter:20,type:'Definition',question:'Describe the nature of radioactive decay.',answer:'It is spontaneous and random: individual decay events are unpredictable, and decay is not affected by ordinary physical or chemical conditions.'},
{ id:'c20d',chapter:20,type:'Formula',question:'Define activity and state its equation.',answer:'Activity is the rate of decay: A = −dN/dt = λN. Its SI unit is the becquerel (Bq), equivalent to s⁻¹.'},
{ id:'c20e',chapter:20,type:'Formula',question:'State the exponential decay equation.',answer:'x = x₀e^(−λt), where x may be activity, undecayed nuclei or corrected count rate.'},
{ id:'c20f',chapter:20,type:'Formula',question:'Relate decay constant and half-life.',answer:'λ = ln 2 / t₁/₂.'},
{ id:'c20g',chapter:20,type:'Formula',question:'State the mass–energy equivalence equation.',answer:'E = mc². A mass change Δm corresponds to energy change ΔE = Δmc².'},
{ id:'c20h',chapter:20,type:'Definition',question:'Define mass defect.',answer:'The difference between the total mass of the separate nucleons and the mass of the bound nucleus.'},
{ id:'c20i',chapter:20,type:'Definition',question:'What is nuclear binding energy?',answer:'The energy required to separate a nucleus completely into its constituent protons and neutrons; it equals the mass defect multiplied by c².'},
{ id:'c20j',chapter:20,type:'Definition',question:'Which quantities are conserved in a nuclear equation?',answer:'Nucleon number, charge and mass-energy are conserved.'},

// Expanded definitions and formula bank, organised from the uploaded lecture notes.
{ id:"add1_01",chapter:1,type:"Definition",question:"List the seven SI base quantities and their units.",answer:"Length: metre (m); mass: kilogram (kg); time: second (s); electric current: ampere (A); thermodynamic temperature: kelvin (K); amount of substance: mole (mol); luminous intensity: candela (cd)."},
{ id:"add1_02",chapter:1,type:"Definition",question:"What is a derived quantity?",answer:"A physical quantity defined in terms of base quantities through multiplication and/or division, e.g. velocity = length/time."},
{ id:"add1_03",chapter:1,type:"Definition",question:"What is the difference between precision and accuracy?",answer:"Precision describes how close repeated measurements are to one another. Accuracy describes how close a measurement is to the true or accepted value."},
{ id:"add1_04",chapter:1,type:"Definition",question:"What is a zero error?",answer:"A systematic error present when an instrument gives a non-zero reading when the true measured quantity is zero."},
{ id:"add1_05",chapter:1,type:"Formula",question:"How are uncertainties combined when quantities are multiplied or divided?",answer:"Add the fractional (or percentage) uncertainties of the quantities."},
{ id:"add1_06",chapter:1,type:"Formula",question:"How does uncertainty propagate when a quantity is raised to a power?",answer:"If y = xⁿ, the fractional uncertainty in y is |n| times the fractional uncertainty in x."},
{ id:"add1_07",chapter:1,type:"Formula",question:"How do you resolve a vector A into perpendicular components?",answer:"For angle θ measured from the x-axis: Aₓ = A cos θ and Aᵧ = A sin θ. Use signs to indicate directions."},
{ id:"add1_08",chapter:1,type:"Formula",question:"How do you find the magnitude and direction of a resultant from perpendicular components?",answer:"R = √(Rₓ² + Rᵧ²); θ = tan⁻¹(Rᵧ/Rₓ), with the correct quadrant chosen from the component signs."},
{ id:"add1_09",chapter:1,type:"Definition",question:"State the SI prefixes from pico to tera.",answer:"pico p = 10⁻¹²; nano n = 10⁻⁹; micro μ = 10⁻⁶; milli m = 10⁻³; centi c = 10⁻²; deci d = 10⁻¹; kilo k = 10³; mega M = 10⁶; giga G = 10⁹; tera T = 10¹²."},
{ id:"add1_10",chapter:1,type:"Definition",question:"How can dimensional analysis test an equation?",answer:"Write each term in base SI dimensions. An equation is dimensionally homogeneous only if both sides and all terms being added have the same dimensions."},
{ id:"add2_01",chapter:2,type:"Definition",question:"Define the normal contact force.",answer:"The contact force exerted by a surface on an object, acting perpendicular to the surface."},
{ id:"add2_02",chapter:2,type:"Definition",question:"What is friction?",answer:"A contact force that opposes relative motion or the tendency for relative motion between surfaces in contact."},
{ id:"add2_03",chapter:2,type:"Definition",question:"What is upthrust?",answer:"The resultant upward force exerted by a fluid on an immersed object due to pressure being greater at greater depth."},
{ id:"add2_04",chapter:2,type:"Definition",question:"State Hooke’s law in words.",answer:"For a spring, extension is directly proportional to applied force provided the limit of proportionality is not exceeded."},
{ id:"add2_05",chapter:2,type:"Definition",question:"What is the moment of a force?",answer:"The product of the force and the perpendicular distance from the pivot to the force’s line of action; moment = Fd."},
{ id:"add2_06",chapter:2,type:"Formula",question:"What is the torque of a couple?",answer:"The product of either force and the perpendicular separation between the two parallel lines of action: τ = Fd."},
{ id:"add2_07",chapter:2,type:"Definition",question:"What is a free-body diagram?",answer:"A diagram showing a chosen body isolated from its surroundings, with all external forces acting on it represented by labelled arrows."},
{ id:"add2_08",chapter:2,type:"Formula",question:"State the conditions for translational equilibrium.",answer:"The vector sum of all external forces is zero: ΣF = 0."},
{ id:"add2_09",chapter:2,type:"Formula",question:"How is the elastic potential energy stored in a Hookean spring calculated?",answer:"Eₚ = ½kx² = ½Fx, where x is extension/compression and F = kx."},
{ id:"add2_10",chapter:2,type:"Definition",question:"What is the centre of gravity?",answer:"The point through which the entire weight of a body may be considered to act."},
{ id:"add3_01",chapter:3,type:"Definition",question:"Define displacement.",answer:"The change in position of an object in a specified direction; it is a vector from initial to final position."},
{ id:"add3_02",chapter:3,type:"Definition",question:"Define velocity.",answer:"The rate of change of displacement with time."},
{ id:"add3_03",chapter:3,type:"Definition",question:"Define speed.",answer:"The rate of change of distance travelled with time; speed is a scalar."},
{ id:"add3_04",chapter:3,type:"Definition",question:"Define linear momentum.",answer:"The product of mass and velocity: p = mv. Momentum is a vector in the direction of velocity."},
{ id:"add3_05",chapter:3,type:"Definition",question:"State Newton’s first law.",answer:"A body remains at rest or moves with constant velocity unless acted on by a resultant external force."},
{ id:"add3_06",chapter:3,type:"Definition",question:"State Newton’s third law.",answer:"If body A exerts a force on body B, body B simultaneously exerts an equal-magnitude, opposite-direction force on body A. The forces act on different bodies."},
{ id:"add3_07",chapter:3,type:"Definition",question:"What does the gradient of a position–time graph represent?",answer:"Velocity (instantaneous velocity is the gradient of the tangent)."},
{ id:"add3_08",chapter:3,type:"Definition",question:"What does the area under a speed–time graph represent?",answer:"Distance travelled."},
{ id:"add3_09",chapter:3,type:"Formula",question:"State the average velocity and average acceleration equations.",answer:"Average velocity = displacement / elapsed time; average acceleration = change in velocity / elapsed time."},
{ id:"add3_10",chapter:3,type:"Formula",question:"Write the uniformly accelerated motion equations using u, v, a, s and t.",answer:"v = u + at; s = ½(u + v)t; s = ut + ½at²; s = vt − ½at²; v² = u² + 2as. These require constant acceleration in a straight line."},
{ id:"add3_11",chapter:3,type:"Formula",question:"How is force related to momentum for a constant-mass body?",answer:"Resultant force F = dp/dt = ma. More generally, resultant force equals rate of change of momentum."},
{ id:"add4_01",chapter:4,type:"Definition",question:"Define work done by a force.",answer:"Work done is the product of the force and displacement in the direction of the force; for constant force W = Fs cos θ."},
{ id:"add4_02",chapter:4,type:"Formula",question:"Define gravitational potential energy change near Earth’s surface.",answer:"For a small height change where g is approximately constant, ΔEₚ = mgΔh."},
{ id:"add4_03",chapter:4,type:"Definition",question:"Define kinetic energy.",answer:"The energy a body possesses because of its motion: Eₖ = ½mv²."},
{ id:"add4_04",chapter:4,type:"Definition",question:"Define power.",answer:"The rate of doing work or transferring energy: P = dW/dt = dE/dt."},
{ id:"add4_05",chapter:4,type:"Formula",question:"State the relationship between power, force and velocity.",answer:"P = F·v; for force parallel to velocity, P = Fv."},
{ id:"add4_06",chapter:4,type:"Definition",question:"Define efficiency.",answer:"Useful energy (or power) output divided by total energy (or power) input, usually expressed as a percentage."},
{ id:"add4_07",chapter:4,type:"Definition",question:"What does the area under a force–displacement graph represent?",answer:"Work done by the force."},
{ id:"add4_08",chapter:4,type:"Definition",question:"Define gravitational field strength.",answer:"Gravitational force per unit mass acting on a small test mass at a point: g = F/m."},
{ id:"add4_09",chapter:4,type:"Definition",question:"Define electric field strength.",answer:"Electric force per unit positive test charge at a point: E = F/q."},
{ id:"add4_10",chapter:4,type:"Formula",question:"What is the relationship between weight and gravitational field strength?",answer:"W = mg, where m is mass and g is gravitational field strength."},
{ id:"add5_01",chapter:5,type:"Definition",question:"What assumptions are made in ideal projectile motion?",answer:"Air resistance is negligible and the gravitational field is uniform, so acceleration is constant and vertically downward; horizontal acceleration is zero."},
{ id:"add5_02",chapter:5,type:"Formula",question:"How are initial velocity components resolved for a projectile launched at angle θ?",answer:"uₓ = u cos θ; uᵧ = u sin θ, where θ is measured above the horizontal."},
{ id:"add5_03",chapter:5,type:"Formula",question:"State the horizontal displacement equation for a projectile.",answer:"x = (u cos θ)t, because horizontal velocity is constant when air resistance is negligible."},
{ id:"add5_04",chapter:5,type:"Formula",question:"State the vertical displacement equation for a projectile launched upward.",answer:"y = (u sin θ)t − ½gt², taking upward as positive and the launch point as y = 0."},
{ id:"add5_05",chapter:5,type:"Formula",question:"What is the time to reach maximum height?",answer:"t = u sin θ / g, since vertical velocity is zero at the highest point."},
{ id:"add5_06",chapter:5,type:"Formula",question:"What is the maximum height above the launch point?",answer:"H = u² sin²θ / (2g)."},
{ id:"add5_07",chapter:5,type:"Formula",question:"For a projectile landing at its launch height, state its time of flight and range.",answer:"T = 2u sin θ/g; R = u² sin 2θ/g, assuming negligible air resistance and constant g."},
{ id:"add5_08",chapter:5,type:"Definition",question:"What is the horizontal velocity of a projectile during flight?",answer:"It remains constant at u cos θ when air resistance is neglected."},
{ id:"add5_09",chapter:5,type:"Formula",question:"What is the vertical velocity after time t?",answer:"vᵧ = u sin θ − gt, taking upward as positive."},
{ id:"add6_01",chapter:6,type:"Definition",question:"Define impulse.",answer:"Impulse is the change in momentum; for a constant resultant force, J = FΔt = Δp."},
{ id:"add6_02",chapter:6,type:"Definition",question:"What does the area under a force–time graph represent?",answer:"Impulse, equal to the change in momentum."},
{ id:"add6_03",chapter:6,type:"Definition",question:"State the principle of conservation of momentum.",answer:"The total momentum of a system remains constant if the resultant external force on the system is zero."},
{ id:"add6_04",chapter:6,type:"Definition",question:"Define an elastic collision.",answer:"A collision in which total momentum and total kinetic energy of the system are conserved."},
{ id:"add6_05",chapter:6,type:"Definition",question:"Define an inelastic collision.",answer:"A collision in which momentum is conserved for an isolated system but total kinetic energy is not conserved."},
{ id:"add6_06",chapter:6,type:"Definition",question:"What is a perfectly inelastic collision?",answer:"A collision in which the objects stick together after impact and move with a common final velocity."},
{ id:"add6_07",chapter:6,type:"Formula",question:"State the momentum equation for two bodies colliding in one dimension.",answer:"m₁u₁ + m₂u₂ = m₁v₁ + m₂v₂, provided the system’s resultant external impulse is negligible."},
{ id:"add6_08",chapter:6,type:"Definition",question:"What happens to relative speed in a one-dimensional elastic collision?",answer:"The speed of approach equals the speed of separation."},
{ id:"add6_09",chapter:6,type:"Formula",question:"Why can a longer collision time reduce the average force?",answer:"For a given momentum change, F̄ = Δp/Δt, so increasing Δt reduces the magnitude of average force."},
{ id:"add7_01",chapter:7,type:"Definition",question:"Define angular displacement.",answer:"The angle swept out by the radius vector of an object moving along a circular path, measured in radians."},
{ id:"add7_02",chapter:7,type:"Definition",question:"Define angular velocity.",answer:"The rate of change of angular displacement: ω = dθ/dt."},
{ id:"add7_03",chapter:7,type:"Definition",question:"Define angular acceleration.",answer:"The rate of change of angular velocity: α = dω/dt."},
{ id:"add7_04",chapter:7,type:"Formula",question:"Relate arc length to angular displacement.",answer:"s = rθ, with θ measured in radians."},
{ id:"add7_05",chapter:7,type:"Formula",question:"Relate tangential speed and angular speed.",answer:"v = rω."},
{ id:"add7_06",chapter:7,type:"Formula",question:"Relate tangential acceleration and angular acceleration.",answer:"aₜ = rα."},
{ id:"add7_07",chapter:7,type:"Formula",question:"State centripetal acceleration in terms of period.",answer:"a = 4π²r/T², directed towards the centre."},
{ id:"add7_08",chapter:7,type:"Formula",question:"State the centripetal force requirement.",answer:"The resultant radial force is F = mv²/r = mrω² and acts towards the centre."},
{ id:"add7_09",chapter:7,type:"Formula",question:"What is the relationship between period and angular speed?",answer:"ω = 2π/T."},
{ id:"add7_10",chapter:7,type:"Definition",question:"Why is centripetal force not an additional force?",answer:"It is the name for the resultant inward force; it may be provided by tension, gravity, friction, a normal force, or a combination of forces."},
{ id:"add8_01",chapter:8,type:"Formula",question:"State Newton’s law of universal gravitation.",answer:"Two point masses attract with force F = GMm/r², where r is the separation of their centres."},
{ id:"add8_02",chapter:8,type:"Definition",question:"Define gravitational potential.",answer:"Work done per unit mass by an external agent in bringing a small test mass from infinity to the point without changing its kinetic energy; zero potential is at infinity."},
{ id:"add8_03",chapter:8,type:"Formula",question:"State the gravitational potential due to a point mass.",answer:"φ = −GM/r, taking gravitational potential to be zero at infinity."},
{ id:"add8_04",chapter:8,type:"Formula",question:"State the gravitational potential energy of two point masses.",answer:"U = −GMm/r, with zero potential energy at infinite separation."},
{ id:"add8_05",chapter:8,type:"Formula",question:"How are gravitational field strength and potential related radially?",answer:"g = −dφ/dr; the field points in the direction of decreasing potential."},
{ id:"add8_06",chapter:8,type:"Formula",question:"What is the gravitational field strength at distance r from a spherical mass M outside it?",answer:"g = GM/r² in magnitude, directed towards the centre."},
{ id:"add8_07",chapter:8,type:"Formula",question:"What is the orbital speed of a circular satellite orbit of radius r?",answer:"v = √(GM/r), obtained by equating gravitational force to centripetal force."},
{ id:"add8_08",chapter:8,type:"Formula",question:"What is the period of a circular orbit?",answer:"T² = 4π²r³/(GM)."},
{ id:"add8_09",chapter:8,type:"Formula",question:"What is escape speed from distance r from a spherical body of mass M?",answer:"vₑ = √(2GM/r), assuming no propulsion after launch and neglecting other bodies and atmosphere."},
{ id:"add8_10",chapter:8,type:"Definition",question:"Define a geostationary satellite.",answer:"A satellite in a circular equatorial orbit, moving west to east with the same period as Earth’s rotation, so it remains above the same point on Earth."},
{ id:"add9_01",chapter:9,type:"Definition",question:"Define simple harmonic motion.",answer:"Motion in which acceleration is directly proportional to displacement from equilibrium and directed towards equilibrium: a = −ω²x."},
{ id:"add9_02",chapter:9,type:"Formula",question:"State the displacement, velocity and acceleration equations for SHM using cosine phase.",answer:"x = A cos ωt; v = −Aω sin ωt; a = −Aω² cos ωt = −ω²x. The phase form depends on initial conditions."},
{ id:"add9_03",chapter:9,type:"Formula",question:"State the maximum speed and acceleration in SHM.",answer:"vₘₐₓ = Aω; aₘₐₓ = Aω²."},
{ id:"add9_04",chapter:9,type:"Formula",question:"State the period of a mass–spring oscillator.",answer:"T = 2π√(m/k), for an ideal spring and small oscillations."},
{ id:"add9_05",chapter:9,type:"Formula",question:"State the period of a simple pendulum.",answer:"T = 2π√(L/g), for small angular oscillations."},
{ id:"add9_06",chapter:9,type:"Formula",question:"What is the total energy in ideal SHM of a mass–spring system?",answer:"E = ½kA² = ½mω²A²; it is constant without damping."},
{ id:"add9_07",chapter:9,type:"Definition",question:"Define natural frequency.",answer:"The frequency at which a system oscillates when displaced and then allowed to oscillate freely without a periodic driving force."},
{ id:"add9_08",chapter:9,type:"Definition",question:"Define forced oscillations.",answer:"Oscillations maintained by an external periodic driving force."},
{ id:"add9_09",chapter:9,type:"Definition",question:"Define resonance.",answer:"The large-amplitude response that occurs when the driving frequency is equal or close to the natural frequency of a system."},
{ id:"add9_10",chapter:9,type:"Definition",question:"How does damping affect an oscillator?",answer:"Damping dissipates mechanical energy, causing the oscillation amplitude to decrease; stronger damping reduces the resonance peak."},
{ id:"add10_01",chapter:10,type:"Definition",question:"Define wavelength.",answer:"The shortest distance between two adjacent points in phase on a wave."},
{ id:"add10_02",chapter:10,type:"Definition",question:"Define frequency.",answer:"The number of complete oscillations or cycles passing a point per unit time."},
{ id:"add10_03",chapter:10,type:"Definition",question:"Define period.",answer:"The time taken for one complete oscillation or cycle: T = 1/f."},
{ id:"add10_04",chapter:10,type:"Definition",question:"Define phase difference.",answer:"A measure of how far one oscillation leads or lags another, expressed as an angle or fraction of a cycle."},
{ id:"add10_05",chapter:10,type:"Formula",question:"State the progressive wave equation.",answer:"v = fλ, where v is wave speed, f is frequency and λ is wavelength."},
{ id:"add10_06",chapter:10,type:"Formula",question:"Write a travelling-wave displacement equation.",answer:"A possible form is y = A sin(ωt − kx + φ), where k = 2π/λ and ω = 2πf; sign and phase depend on direction and origin."},
{ id:"add10_07",chapter:10,type:"Definition",question:"Define intensity of a wave.",answer:"Power transmitted per unit area perpendicular to the direction of energy transfer."},
{ id:"add10_08",chapter:10,type:"Formula",question:"How does intensity depend on amplitude for a wave of fixed frequency in the same medium?",answer:"I ∝ A²."},
{ id:"add10_09",chapter:10,type:"Definition",question:"What is polarisation?",answer:"Restriction of wave oscillations to a particular direction perpendicular to the direction of propagation."},
{ id:"add10_10",chapter:10,type:"Definition",question:"Why can longitudinal waves not be polarised?",answer:"Their oscillations are parallel to the direction of propagation, so there is no transverse oscillation direction to restrict."},
{ id:"add11_01",chapter:11,type:"Definition",question:"State the principle of superposition of waves.",answer:"When waves overlap, the resultant displacement at a point is the sum of the individual displacements at that point."},
{ id:"add11_02",chapter:11,type:"Definition",question:"Define coherent sources.",answer:"Sources that emit waves of the same frequency and maintain a constant phase difference."},
{ id:"add11_03",chapter:11,type:"Definition",question:"What is constructive interference?",answer:"Interference producing maximum resultant amplitude when waves arrive in phase; path difference = nλ."},
{ id:"add11_04",chapter:11,type:"Definition",question:"What is destructive interference?",answer:"Interference producing minimum resultant amplitude when waves arrive in antiphase; path difference = (n + ½)λ."},
{ id:"add11_05",chapter:11,type:"Formula",question:"State the double-slit fringe-spacing equation.",answer:"x = λD/a, where x is adjacent fringe separation, D is slit-to-screen distance and a is slit separation; for small angles."},
{ id:"add11_06",chapter:11,type:"Formula",question:"State the path-difference conditions for double-slit maxima and minima.",answer:"Maxima: path difference = nλ. Minima: path difference = (n + ½)λ, for integer n."},
{ id:"add11_07",chapter:11,type:"Formula",question:"State the diffraction grating equation.",answer:"d sin θ = nλ for principal maxima, where d is grating spacing and n is an integer order."},
{ id:"add11_08",chapter:11,type:"Formula",question:"State the single-slit diffraction minima condition.",answer:"b sin θ = nλ for n = 1, 2, 3, …, where b is slit width."},
{ id:"add11_09",chapter:11,type:"Definition",question:"Define a node in a stationary wave.",answer:"A point of zero displacement at all times."},
{ id:"add11_10",chapter:11,type:"Definition",question:"Define an antinode in a stationary wave.",answer:"A point where the oscillation amplitude is maximum."},
{ id:"add11_11",chapter:11,type:"Definition",question:"How is a stationary wave formed?",answer:"By superposition of two waves of the same frequency and amplitude travelling in opposite directions."},
{ id:"add11_12",chapter:11,type:"Formula",question:"How far apart are adjacent nodes or adjacent antinodes?",answer:"λ/2. The separation between a node and its nearest antinode is λ/4."},
{ id:"add12_01",chapter:12,type:"Definition",question:"Define temperature using the kinetic model.",answer:"Temperature in an ideal gas is proportional to the mean translational kinetic energy of its molecules."},
{ id:"add12_02",chapter:12,type:"Formula",question:"State the ideal gas equation.",answer:"pV = nRT = NkBT, where n is amount in moles, N is number of molecules, R is the molar gas constant and kB is Boltzmann’s constant."},
{ id:"add12_03",chapter:12,type:"Formula",question:"State the relation between amount of substance and number of molecules.",answer:"N = nNₐ, where Nₐ is the Avogadro constant."},
{ id:"add12_04",chapter:12,type:"Formula",question:"State the mean translational kinetic energy of an ideal gas molecule.",answer:"⟨Eₖ⟩ = 3/2 kBT."},
{ id:"add12_05",chapter:12,type:"Formula",question:"State the root-mean-square speed of ideal gas molecules.",answer:"cᵣₘₛ = √(3kBT/m) = √(3RT/M), where m is molecular mass and M is molar mass."},
{ id:"add12_06",chapter:12,type:"Definition",question:"What assumptions define an ideal gas model?",answer:"Molecules have negligible volume compared with the container, exert no intermolecular forces except during collisions, and undergo perfectly elastic collisions; motion is random."},
{ id:"add12_07",chapter:12,type:"Formula",question:"State Boyle’s law.",answer:"For a fixed amount of gas at constant temperature, pV = constant."},
{ id:"add12_08",chapter:12,type:"Formula",question:"State Charles’s law.",answer:"For a fixed amount of gas at constant pressure, V/T = constant, with T measured in kelvin."},
{ id:"add12_09",chapter:12,type:"Formula",question:"State the pressure law.",answer:"For a fixed amount of gas at constant volume, p/T = constant, with T measured in kelvin."},
{ id:"add12_10",chapter:12,type:"Definition",question:"What is absolute zero?",answer:"0 K, the lower limit of thermodynamic temperature; the ideal-gas extrapolation gives zero pressure at constant volume."},
{ id:"add13_01",chapter:13,type:"Definition",question:"Define internal energy.",answer:"The sum of the microscopic kinetic and potential energies of the particles in a system."},
{ id:"add13_02",chapter:13,type:"Formula",question:"State the first law of thermodynamics using work done by the system.",answer:"ΔU = Q − W, where Q is heat supplied to the system and W is work done by the system."},
{ id:"add13_03",chapter:13,type:"Formula",question:"How is work done by a gas calculated at constant pressure?",answer:"W = pΔV. Expansion gives positive work done by the gas; compression gives negative work done by the gas under this convention."},
{ id:"add13_04",chapter:13,type:"Definition",question:"What is an isothermal process?",answer:"A thermodynamic process at constant temperature. For an ideal gas, internal energy change is zero."},
{ id:"add13_05",chapter:13,type:"Definition",question:"What is an adiabatic process?",answer:"A process in which no heat is transferred to or from the system: Q = 0."},
{ id:"add13_06",chapter:13,type:"Definition",question:"What is an isobaric process?",answer:"A process at constant pressure."},
{ id:"add13_07",chapter:13,type:"Definition",question:"What is an isochoric process?",answer:"A process at constant volume; boundary work pΔV is zero."},
{ id:"add13_08",chapter:13,type:"Definition",question:"What does the area under a p–V graph represent?",answer:"Work done by the gas during the process, with sign determined by the direction of volume change."},
{ id:"add13_09",chapter:13,type:"Definition",question:"What is the net work done over a complete cycle on a p–V diagram?",answer:"The signed area enclosed by the cycle."},
{ id:"add13_10",chapter:13,type:"Formula",question:"State the change in internal energy of a fixed amount of ideal gas.",answer:"ΔU = nCᵥΔT, where Cᵥ is molar heat capacity at constant volume."},
{ id:"add14_01",chapter:14,type:"Definition",question:"Define electric field strength.",answer:"Electric force per unit positive test charge at a point: E = F/q."},
{ id:"add14_02",chapter:14,type:"Formula",question:"State Coulomb’s law for two point charges.",answer:"F = |Qq|/(4πε₀r²) in vacuum; the force acts along the line joining the charges and may be attractive or repulsive."},
{ id:"add14_03",chapter:14,type:"Formula",question:"State the electric field strength due to a point charge.",answer:"E = Q/(4πε₀r²) in signed radial form; magnitude is |Q|/(4πε₀r²)."},
{ id:"add14_04",chapter:14,type:"Definition",question:"Define electric potential at a point.",answer:"Work done per unit positive charge by an external agent in bringing a small test charge from infinity to the point without changing kinetic energy."},
{ id:"add14_05",chapter:14,type:"Formula",question:"State electric potential due to a point charge.",answer:"V = Q/(4πε₀r), taking potential to be zero at infinity."},
{ id:"add14_06",chapter:14,type:"Formula",question:"State the electric potential energy of two point charges.",answer:"U = Qq/(4πε₀r), taking zero potential energy at infinite separation."},
{ id:"add14_07",chapter:14,type:"Formula",question:"What is the relationship between electric field and potential in one dimension?",answer:"E = −dV/dx; the electric field points in the direction of decreasing electric potential."},
{ id:"add14_08",chapter:14,type:"Formula",question:"State the relationship between electric potential difference and work.",answer:"ΔV = ΔEₚ/q; work done by the electric field on charge q is −qΔV."},
{ id:"add14_09",chapter:14,type:"Formula",question:"State the electric field between parallel plates.",answer:"E = V/d for a uniform field, where V is potential difference and d is plate separation."},
{ id:"add14_10",chapter:14,type:"Definition",question:"What is an equipotential surface?",answer:"A surface on which electric potential is constant; no work is done by the electric field moving a charge along it."},
{ id:"add15_01",chapter:15,type:"Definition",question:"Define electric current.",answer:"The rate of flow of electric charge: I = dQ/dt."},
{ id:"add15_02",chapter:15,type:"Definition",question:"Define electromotive force (e.m.f.).",answer:"Energy supplied by a source per unit charge passing through it."},
{ id:"add15_03",chapter:15,type:"Definition",question:"Define potential difference.",answer:"Energy transferred from electrical to other forms per unit charge passing between two points."},
{ id:"add15_04",chapter:15,type:"Formula",question:"State the relationship between current, charge and time for steady current.",answer:"Q = It."},
{ id:"add15_05",chapter:15,type:"Formula",question:"State the drift-current relationship.",answer:"I = nAqv, where n is charge-carrier number density, A is cross-sectional area, q is charge magnitude and v is drift speed."},
{ id:"add15_06",chapter:15,type:"Definition",question:"State Ohm’s law.",answer:"For a conductor at constant temperature and other physical conditions, current is directly proportional to potential difference across it."},
{ id:"add15_07",chapter:15,type:"Definition",question:"Define resistivity.",answer:"A material property defined by ρ = RA/L for a uniform conductor, where R is resistance, A cross-sectional area and L length."},
{ id:"add15_08",chapter:15,type:"Formula",question:"State the resistance equation for a uniform wire.",answer:"R = ρL/A."},
{ id:"add15_09",chapter:15,type:"Formula",question:"How does resistance depend on temperature for a metallic conductor over a limited range?",answer:"R ≈ R₀[1 + α(T − T₀)], where α is the temperature coefficient of resistance at reference temperature T₀."},
{ id:"add15_10",chapter:15,type:"Definition",question:"What is conventional current direction?",answer:"The direction in which positive charge would flow; in a metal it is opposite to electron drift."},
{ id:"add16_01",chapter:16,type:"Formula",question:"State the electrical power equations.",answer:"P = IV = I²R = V²/R for a resistor."},
{ id:"add16_02",chapter:16,type:"Formula",question:"State the electrical energy transferred over time.",answer:"E = Pt = VIt; for a resistor E = I²Rt = V²t/R when values are constant."},
{ id:"add16_03",chapter:16,type:"Definition",question:"State Kirchhoff’s first law.",answer:"The sum of currents entering a junction equals the sum of currents leaving it, reflecting conservation of charge."},
{ id:"add16_04",chapter:16,type:"Definition",question:"State Kirchhoff’s second law.",answer:"The algebraic sum of e.m.f.s and potential drops around a closed loop is zero, reflecting conservation of energy."},
{ id:"add16_05",chapter:16,type:"Formula",question:"How do resistors combine in series?",answer:"Rₜₒₜ = R₁ + R₂ + …; the same current flows through each resistor."},
{ id:"add16_06",chapter:16,type:"Formula",question:"How do resistors combine in parallel?",answer:"1/Rₜₒₜ = 1/R₁ + 1/R₂ + …; each branch has the same potential difference."},
{ id:"add16_07",chapter:16,type:"Formula",question:"State the terminal potential difference of a source with internal resistance.",answer:"V = ε − Ir when delivering current, where ε is e.m.f. and r is internal resistance."},
{ id:"add16_08",chapter:16,type:"Definition",question:"What is lost volts?",answer:"The potential difference across the internal resistance of a source when current flows: Ir."},
{ id:"add16_09",chapter:16,type:"Formula",question:"How can the e.m.f. and internal resistance be found from terminal voltage against current?",answer:"From V = ε − Ir, the vertical intercept is ε and the gradient is −r."},
{ id:"add16_10",chapter:16,type:"Definition",question:"What is a potential divider?",answer:"A series resistor network that divides a supply potential difference in proportion to the resistances, when loading is negligible."},
{ id:"add17_01",chapter:17,type:"Formula",question:"State the magnetic force on a moving charge.",answer:"F = |q|vB sin θ, where θ is the angle between velocity and magnetic field; direction follows the appropriate charge and hand rule."},
{ id:"add17_02",chapter:17,type:"Formula",question:"State the magnetic force on a straight current-carrying wire.",answer:"F = BIL sin θ, where θ is the angle between current direction and magnetic field."},
{ id:"add17_03",chapter:17,type:"Formula",question:"What is the force on a charged particle moving parallel to a magnetic field?",answer:"Zero, because F = |q|vB sin θ and θ = 0."},
{ id:"add17_04",chapter:17,type:"Definition",question:"What is the path of a charged particle entering a uniform magnetic field perpendicular to its velocity?",answer:"Circular, if the magnetic force is the only force, because the force is perpendicular to velocity and provides centripetal force."},
{ id:"add17_05",chapter:17,type:"Formula",question:"State the radius of the circular path of a charged particle in a perpendicular magnetic field.",answer:"r = mv/(|q|B)."},
{ id:"add17_06",chapter:17,type:"Formula",question:"State the cyclotron period for non-relativistic motion in a uniform magnetic field.",answer:"T = 2πm/(|q|B), independent of speed and orbit radius."},
{ id:"add17_07",chapter:17,type:"Formula",question:"State the force between two long parallel current-carrying wires.",answer:"F/L = μ₀I₁I₂/(2πd) in vacuum, where d is their separation."},
{ id:"add17_08",chapter:17,type:"Definition",question:"What is the direction of force between parallel currents?",answer:"Currents in the same direction attract; currents in opposite directions repel."},
{ id:"add17_09",chapter:17,type:"Definition",question:"What is magnetic flux density?",answer:"A measure of the strength of a magnetic field; for a wire perpendicular to the field, B = F/(IL)."},
{ id:"add17_10",chapter:17,type:"Formula",question:"How does a velocity selector work?",answer:"Crossed electric and magnetic fields allow particles to pass undeflected when electric and magnetic forces balance: qE = qvB, so v = E/B."},
{ id:"add18_01",chapter:18,type:"Definition",question:"Define magnetic flux.",answer:"A measure of magnetic field passing through a surface: Φ = BA cos θ for a uniform field, where θ is between the field and surface normal."},
{ id:"add18_02",chapter:18,type:"Definition",question:"Define magnetic flux linkage.",answer:"The product of the number of turns and magnetic flux through each turn: NΦ."},
{ id:"add18_03",chapter:18,type:"Formula",question:"State Faraday’s law.",answer:"The magnitude of induced e.m.f. is proportional to the rate of change of magnetic flux linkage: |ε| = |d(NΦ)/dt|."},
{ id:"add18_04",chapter:18,type:"Definition",question:"State Lenz’s law.",answer:"The induced current is in a direction such that its magnetic effect opposes the change in flux that produced it."},
{ id:"add18_05",chapter:18,type:"Formula",question:"State the motional e.m.f. equation for a rod moving perpendicular to its length and magnetic field.",answer:"ε = Blv, where l is the rod length within the field and v is its speed."},
{ id:"add18_06",chapter:18,type:"Formula",question:"State the ideal transformer ratios.",answer:"Vₛ/Vₚ = Nₛ/Nₚ and Iₛ/Iₚ = Nₚ/Nₛ; input power equals output power for an ideal transformer."},
{ id:"add18_07",chapter:18,type:"Definition",question:"Why is a changing magnetic flux needed for electromagnetic induction?",answer:"A changing flux linkage induces an e.m.f.; a steady flux linkage induces no e.m.f."},
{ id:"add18_08",chapter:18,type:"Definition",question:"What is self-inductance?",answer:"The property of a circuit whereby a change in its own current induces an e.m.f. that opposes the change."},
{ id:"add18_09",chapter:18,type:"Formula",question:"State the self-induced e.m.f. equation.",answer:"ε = −L(dI/dt), where L is the inductance; the minus sign represents Lenz’s law."},
{ id:"add18_10",chapter:18,type:"Formula",question:"State the energy stored in an inductor.",answer:"E = ½LI²."},
{ id:"add19_01",chapter:19,type:"Definition",question:"What is the threshold frequency in the photoelectric effect?",answer:"The minimum frequency of incident electromagnetic radiation required to emit photoelectrons from a particular material."},
{ id:"add19_02",chapter:19,type:"Formula",question:"State Einstein’s photoelectric equation.",answer:"hf = φ + Kₘₐₓ = φ + eVₛ, where φ is work function and Vₛ is stopping potential."},
{ id:"add19_03",chapter:19,type:"Definition",question:"Define work function.",answer:"The minimum energy needed to remove an electron from the surface of a material."},
{ id:"add19_04",chapter:19,type:"Formula",question:"How is threshold frequency related to work function?",answer:"φ = hf₀, where f₀ is threshold frequency."},
{ id:"add19_05",chapter:19,type:"Definition",question:"What is the effect of increasing light intensity above threshold frequency?",answer:"It increases the rate of photon arrival and typically the photoelectric current, but does not increase the maximum kinetic energy of photoelectrons."},
{ id:"add19_06",chapter:19,type:"Definition",question:"What is the effect of increasing frequency above threshold?",answer:"Photon energy increases, so the maximum photoelectron kinetic energy increases according to Kₘₐₓ = hf − φ."},
{ id:"add19_07",chapter:19,type:"Formula",question:"What is de Broglie wavelength in terms of kinetic energy for a non-relativistic particle?",answer:"λ = h/√(2mEₖ), using Eₖ = p²/(2m)."},
{ id:"add19_08",chapter:19,type:"Formula",question:"What is the normalisation condition for a one-dimensional wavefunction?",answer:"∫ |Ψ(x)|² dx = 1 over all allowed positions; |Ψ|² is probability density."},
{ id:"add19_09",chapter:19,type:"Formula",question:"State the allowed wavelengths for a particle in a one-dimensional infinite well of width L.",answer:"λₙ = 2L/n, where n = 1, 2, 3, …"},
{ id:"add19_10",chapter:19,type:"Formula",question:"State the wavefunction form for a particle in a one-dimensional infinite square well from x = 0 to L.",answer:"Ψₙ(x) ∝ sin(nπx/L) inside the well and Ψ = 0 outside; the normalised form is √(2/L) sin(nπx/L)."},
{ id:"add19_11",chapter:19,type:"Formula",question:"State the energy levels of a particle in a one-dimensional infinite square well.",answer:"Eₙ = n²h²/(8mL²), n = 1, 2, 3, …"},
{ id:"add19_12",chapter:19,type:"Definition",question:"What is the ground state?",answer:"The lowest allowed energy state of a quantum system; for the infinite well, n = 1."},
{ id:"add19_13",chapter:19,type:"Formula",question:"How is photon energy related to an atomic transition?",answer:"|ΔE| = hf = hc/λ; emission occurs when an electron moves to a lower level and absorption when it moves to a higher level."},
{ id:"add19_14",chapter:19,type:"Definition",question:"What evidence supports the wave nature of particles?",answer:"Electron diffraction and interference, including a double-slit interference pattern built up by particles detected one at a time."},
{ id:"add20_01",chapter:20,type:"Definition",question:"What is the nuclide notation for a nucleus?",answer:"ᴬ_ZX, where Z is proton number and A is nucleon number; neutron number = A − Z."},
{ id:"add20_02",chapter:20,type:"Definition",question:"What is an alpha particle?",answer:"A helium-4 nucleus containing two protons and two neutrons, with charge +2e."},
{ id:"add20_03",chapter:20,type:"Definition",question:"What is a beta-minus particle?",answer:"A high-speed electron emitted in beta-minus decay when a neutron changes into a proton, an electron and an antineutrino."},
{ id:"add20_04",chapter:20,type:"Definition",question:"What is a gamma ray?",answer:"A high-frequency electromagnetic photon emitted by a nucleus as it loses excess energy; it has no charge and no rest mass."},
{ id:"add20_05",chapter:20,type:"Formula",question:"State the radioactive decay law.",answer:"N = N₀e^(−λt); similarly, A = A₀e^(−λt) for activity."},
{ id:"add20_06",chapter:20,type:"Definition",question:"Define half-life.",answer:"The time taken for the number of undecayed nuclei or the activity of a sample to fall to half its initial value."},
{ id:"add20_07",chapter:20,type:"Definition",question:"Define decay constant.",answer:"The probability per unit time that a nucleus decays; activity A = λN. Its SI unit is s⁻¹."},
{ id:"add20_08",chapter:20,type:"Formula",question:"How is corrected count rate related to measured count rate?",answer:"Corrected count rate = measured sample count rate − background count rate, provided both rates are measured comparably."},
{ id:"add20_09",chapter:20,type:"Definition",question:"Define binding energy per nucleon.",answer:"The total nuclear binding energy divided by the number of nucleons; it indicates average binding per nucleon."},
{ id:"add20_10",chapter:20,type:"Formula",question:"State the binding-energy relation from mass defect.",answer:"Eᵦ = Δmc², where Δm is the mass defect. If Δm is in atomic mass units, convert it to kg or use 1 u c² ≈ 931.5 MeV."},
{ id:"add20_11",chapter:20,type:"Definition",question:"What is nuclear fission?",answer:"The splitting of a heavy nucleus into two or more lighter nuclei, usually releasing neutrons and energy."},
{ id:"add20_12",chapter:20,type:"Definition",question:"What is nuclear fusion?",answer:"The joining of light nuclei to form a heavier nucleus, with energy released when the products have greater total binding energy."},
{ id:"add20_13",chapter:20,type:"Definition",question:"Why can fission or fusion release energy?",answer:"The products have greater total binding energy (greater binding energy per nucleon in the relevant mass range); the mass difference is released as energy, ΔE = Δmc²."},
{ id:"add20_14",chapter:20,type:"Definition",question:"What is the activity of a radioactive source?",answer:"The number of nuclear decays per unit time: A = −dN/dt = λN, measured in becquerels (Bq)."},
];
